CONCAT(CAST(COALESCE(CONVERT(VARCHAR(40), CAST([id] AS BIGINT)), '<NULL>') AS VARCHAR(MAX)), '|~|', COALESCE(RTRIM([code]), '<NULL>'), '|~|', COALESCE(RTRIM([name]), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(60), CAST([amount] AS DECIMAL(38,6))), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(60), CAST([ratio] AS DECIMAL(38,6))), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(40), CAST([units] AS BIGINT)), '<NULL>'), '|~|', COALESCE(CASE WHEN [is_active] IS NULL THEN NULL WHEN [is_active] = 1 THEN '1' ELSE '0' END, '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(10), [born_on], 23), '<NULL>'), '|~|', COALESCE(CONVERT(VARCHAR(26), CAST([updated_at] AS DATETIME2(6)), 121), '<NULL>'))
